<div><div class="mb-6"><h1 class="text-2xl font-bold">Bibliotecă media</h1><p class="text-stone-500">Imagini reutilizabile pentru conținut și catalog.</p></div><form wire:submit="upload" class="mb-5 flex gap-3 rounded-xl border bg-white p-4"><input type="file" multiple accept="image/*" wire:model="files" class="flex-1 rounded border p-2"><button class="rounded bg-lime-400 px-5 font-semibold">Încarcă</button></form><div class="grid grid-cols-2 gap-4 md:grid-cols-4 xl:grid-cols-6">@foreach($assets as $asset)<div class="rounded-xl border bg-white p-2"><img src="{{ Storage::disk($asset->disk)->url($asset->path) }}" class="aspect-square w-full rounded object-cover"><div class="mt-2 truncate text-xs" title="{{ $asset->path }}">{{ $asset->filename }}</div><button wire:click="delete({{ $asset->id }})" wire:confirm="Ștergi fișierul din bibliotecă?" class="mt-1 text-xs text-red-600">Șterge</button></div>@endforeach</div><div class="mt-4">{{ $assets->links() }}</div></div>
